 17→// --- Golden output tests ---
 18→
 19→func TestCompact_SimpleConversation(t *testing.T) {
 20→	t.Parallel()
 21→
 22→	input := []byte(`{"type":"user","uuid":"u1","timestamp":"2026-01-01T00:00:00Z","parentUuid":"","cwd":"/repo","message":{"content":"hello"}}
 23→{"type":"assistant","timestamp":"2026-01-01T00:00:01Z","requestId":"req-1","message":{"id":"msg-1","content":[{"type":"text","text":"Hi!"}]}}
 24→`)
 25→
 26→	expected := []string{
 27→		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"user","ts":"2026-01-01T00:00:00Z","content":"hello"}`,
 28→		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"assistant","ts":"2026-01-01T00:00:01Z","id":"msg-1","content":[{"type":"text","text":"Hi!"}]}`,
 29→	}
 30→
 31→	result, err := Compact(input, defaultOpts)
 32→	if err != nil {
 33→		t.Fatalf("unexpected error: %v", err)
 34→	}
 35→	assertJSONLines(t, result, expected)
 36→}
