### Task 5: Create `gemini.go` — Gemini format converter (new)

**Files:**
- Create: `cmd/entire/cli/transcript/compact/gemini.go`

The Gemini transcript is a single JSON object with structure:
```json
{
  "sessionId": "...",
  "messages": [
    {
      "id": "...",
      "timestamp": "2026-03-18T21:05:13.497Z",
      "type": "user" | "gemini" | "info",
      "content": "...",
      "toolCalls": [...],
      "thoughts": [...],
      "tokens": {...}
    }
  ]
}
```

Key differences from other formats:
- `type: "gemini"` for assistant messages (not "assistant")
- `type: "info"` for system messages (should be dropped)
- `toolCalls` array at message level (not inside content blocks)
- `thoughts` array (analogous to Claude's thinking blocks — should be stripped)
- Timestamps are ISO strings (not ms integers like OpenCode)

- [ ] **Step 1: Create `gemini.go`**

```go
package compact

import (
	"bytes"
	"encoding/json"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// isGeminiFormat checks whether content is a single JSON object with the
// Gemini CLI session shape (top-level "sessionId" and "messages" keys, no "info").
func isGeminiFormat(content []byte) bool {
	trimmed := bytes.TrimSpace(content)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return false
	}
	var probe struct {
		SessionID *json.RawMessage `json:"sessionId"`
		Messages  *json.RawMessage `json:"messages"`
		Info      *json.RawMessage `json:"info"`
	}
	if json.Unmarshal(trimmed, &probe) != nil {
		return false
	}
	// Gemini has sessionId + messages but no info (info distinguishes OpenCode).
	return probe.SessionID != nil && probe.Messages != nil && probe.Info == nil
}

type geminiMessage struct {
	ID        string                       `json:"id"`
	Timestamp string                       `json:"timestamp"`
	Type      string                       `json:"type"`
	Content   string                       `json:"content"`
	ToolCalls []geminiToolCall              `json:"toolCalls"`
}

type geminiToolCall struct {
	ID     string                       `json:"id"`
	Name   string                       `json:"name"`
	Args   map[string]json.RawMessage   `json:"args"`
	Result []geminiToolResult            `json:"result"`
	Status string                       `json:"status"`
}

type geminiToolResult struct {
	FunctionResponse struct {
		ID       string                     `json:"id"`
		Name     string                     `json:"name"`
		Response map[string]json.RawMessage `json:"response"`
	} `json:"functionResponse"`
}

// geminiDroppedTypes are Gemini message types that carry no transcript-relevant data.
var geminiDroppedTypes = map[string]bool{
	"info": true,
}

func compactGemini(content []byte, opts CompactOptions) ([]byte, error) {
	var session struct {
		Messages []geminiMessage `json:"messages"`
	}
	if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
		return nil, fmt.Errorf("parsing gemini session: %w", err)
	}

	meta := newCompactMeta(opts)
	var result []byte

	for _, msg := range session.Messages {
		if geminiDroppedTypes[msg.Type] {
			continue
		}

		ts := mustMarshal(msg.Timestamp)

		switch {
		case msg.Type == transcript.TypeUser:
			b := convertGeminiUser(msg, ts, meta)
			if b != nil {
				result = append(result, b...)
				result = append(result, '\n')
			}
		case assistantAliases[msg.Type]:
			b := convertGeminiAssistant(msg, ts, meta)
			if b != nil {
				result = append(result, b...)
				result = append(result, '\n')
			}
		}
	}

	return result, nil
}

func convertGeminiUser(msg geminiMessage, ts json.RawMessage, meta compactMeta) []byte {
	return marshalOrdered(
		"v", meta.v,
		"agent", meta.agent,
		"cli_version", meta.cliVersion,
		"type", mustMarshal(transcript.TypeUser),
		"ts", ts,
		"id", mustMarshal(msg.ID),
		"content", mustMarshal(msg.Content),
	)
}

func convertGeminiAssistant(msg geminiMessage, ts json.RawMessage, meta compactMeta) []byte {
	content := make([]map[string]json.RawMessage, 0)

	// Add text content if present.
	if msg.Content != "" {
		content = append(content, map[string]json.RawMessage{
			"type": mustMarshal(transcript.ContentTypeText),
			"text": mustMarshal(msg.Content),
		})
	}

	// Convert toolCalls to tool_use content blocks.
	for _, tc := range msg.ToolCalls {
		toolBlock := map[string]json.RawMessage{
			"type": mustMarshal(transcript.ContentTypeToolUse),
			"id":   mustMarshal(tc.ID),
			"name": mustMarshal(tc.Name),
		}
		if tc.Args != nil {
			argsJSON, err := json.Marshal(tc.Args)
			if err == nil {
				toolBlock["input"] = argsJSON
			}
		}
		// Extract compact result from functionResponse.
		if len(tc.Result) > 0 {
			resp := tc.Result[0].FunctionResponse.Response
			toolResult := map[string]string{
				"status": tc.Status,
			}
			if output := unquote(resp["output"]); output != "" {
				toolResult["output"] = output
			}
			toolBlock["result"] = mustMarshal(toolResult)
		}
		content = append(content, toolBlock)
	}

	contentJSON, err := json.Marshal(content)
	if err != nil {
		return nil
	}

	return marshalOrdered(
		"v", meta.v,
		"agent", meta.agent,
		"cli_version", meta.cliVersion,
		"type", mustMarshal(transcript.TypeAssistant),
		"ts", ts,
		"id", mustMarshal(msg.ID),
		"content", json.RawMessage(contentJSON),
	)
}
```

