 27→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 28→// transcript line. It checks the "type" field, then falls back to "role".
 29→// Returns "" for unrecognised or dropped entries.
 30→func normalizeKind(raw map[string]json.RawMessage) string {
 31→	kind := unquote(raw["type"])
 32→	if kind == "" {
 33→		kind = unquote(raw["role"])
 34→	}
 35→
 36→	if droppedTypes[kind] {
 37→		return ""
 38→	}
 39→	if userAliases[kind] {
 40→		return transcript.TypeUser
 41→	}
 42→	if assistantAliases[kind] {
