 48→// compactJSONL converts JSONL content (Claude Code, Cursor, Factory AI Droid)
 49→// into the compact transcript format, one line at a time.
 50→func compactJSONL(content []byte, opts Options) ([]byte, error) {
 51→	meta := newCompactMeta(opts)
 52→	reader := bufio.NewReader(bytes.NewReader(content))
 53→	var result []byte
 54→
 55→	for {
 56→		lineBytes, err := reader.ReadBytes('\n')
 57→		if err != nil && err != io.EOF {
 58→			return nil, fmt.Errorf("reading JSONL line: %w", err)
 59→		}
 60→
 61→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 62→			outputLines := convertLine(lineBytes, meta)
 63→			for _, ol := range outputLines {
 64→				result = append(result, ol...)
 65→				result = append(result, '\n')
 66→			}
 67→		}
 68→
 69→		if err == io.EOF {
 70→			break
 71→		}
 72→	}
 73→
 74→	return result, nil
 75→}
