 77→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
 78→func convertLine(lineBytes []byte, meta compactMeta) [][]byte {
 79→	var raw map[string]json.RawMessage
 80→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
 81→		return nil
 82→	}
 83→
 84→	raw = unwrapEnvelope(raw)
 85→
 86→	switch normalizeKind(raw) {
 87→	case transcript.TypeAssistant:
 88→		return convertAssistant(raw, meta)
 89→	case transcript.TypeUser:
 90→		return convertUser(raw, meta)
 91→	default:
 92→		return nil
 93→	}
 94→}
