 96→func convertAssistant(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
 97→	var id, content json.RawMessage
 98→	if msg := parseMessage(raw); msg != nil {
 99→		id = msg["id"]
100→		if contentRaw, ok := msg["content"]; ok {
101→			content = stripAssistantContent(contentRaw)
102→		}
103→	}
104→
105→	b := marshalOrdered(
106→		"v", meta.v,
107→		"agent", meta.agent,
108→		"cli_version", meta.cliVersion,
109→		"type", mustMarshal(transcript.TypeAssistant),
110→		"ts", raw["timestamp"],
111→		"id", id,
112→		"content", content,
113→	)
114→	if b == nil {
115→		return nil
116→	}
117→	return [][]byte{b}
118→}
