120→func convertUser(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
121→	var lines [][]byte
122→	ts := raw["timestamp"]
123→
124→	var textContent string
125→	var toolResults []toolResultEntry
126→
127→	if msg := parseMessage(raw); msg != nil {
128→		if contentRaw, ok := msg["content"]; ok {
129→			textContent, toolResults = extractUserContent(contentRaw)
130→		}
131→	}
132→
133→	b := marshalOrdered(
134→		"v", meta.v,
135→		"agent", meta.agent,
136→		"cli_version", meta.cliVersion,
137→		"type", mustMarshal(transcript.TypeUser),
138→		"ts", ts,
139→		"content", mustMarshal(textContent),
140→	)
141→	if b != nil {
142→		lines = append(lines, b)
143→	}
144→
145→	// full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
146→	// When there are multiple tool_result blocks, each user_tool_result line gets the
147→	// same minimized result — a known limitation of the source format.
148→	var minimizedResult json.RawMessage
149→	if turRaw, ok := raw["toolUseResult"]; ok {
150→		minimizedResult = minimizeToolUseResult(turRaw)
151→	}
152→
153→	for _, tr := range toolResults {
154→		result := minimizedResult
155→		if result == nil {
156→			result = mustMarshal(map[string]interface{}{})
157→		}
158→
159→		b := marshalOrdered(
160→			"v", meta.v,
161→			"agent", meta.agent,
162→			"cli_version", meta.cliVersion,
163→			"type", mustMarshal("user_tool_result"),
164→			"ts", ts,
165→			"tool_use_id", mustMarshal(tr.toolUseID),
166→			"result", result,
167→		)
168→		if b != nil {
169→			lines = append(lines, b)
170→		}
171→	}
172→
173→	return lines
174→}
