205→// extractUserContent separates user message content into text and tool_result entries.
206→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
207→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
208→	var str string
209→	if json.Unmarshal(contentRaw, &str) == nil {
210→		return textutil.StripIDEContextTags(str), nil
211→	}
212→
213→	var blocks []map[string]json.RawMessage
214→	if json.Unmarshal(contentRaw, &blocks) != nil {
215→		return "", nil
216→	}
217→
218→	var texts []string
219→	var toolResults []toolResultEntry
220→
221→	for _, block := range blocks {
222→		blockType := unquote(block["type"])
223→
224→		if blockType == "tool_result" {
225→			toolResults = append(toolResults, toolResultEntry{
226→				toolUseID: unquote(block["tool_use_id"]),
227→			})
228→			continue
229→		}
230→
231→		if blockType == transcript.ContentTypeText {
232→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
233→			if stripped != "" {
234→				texts = append(texts, stripped)
235→			}
236→		}
237→	}
238→
239→	return strings.Join(texts, "\n\n"), toolResults
240→}
