242→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
243→	var str string
244→	if json.Unmarshal(contentRaw, &str) == nil {
245→		return contentRaw
246→	}
247→
248→	var blocks []map[string]json.RawMessage
249→	if json.Unmarshal(contentRaw, &blocks) != nil {
250→		return contentRaw
251→	}
252→
253→	result := make([]map[string]json.RawMessage, 0, len(blocks))
254→	for _, block := range blocks {
255→		blockType := unquote(block["type"])
256→
257→		if blockType == "thinking" || blockType == "redacted_thinking" {
258→			continue
259→		}
260→
261→		if blockType == transcript.ContentTypeToolUse {
262→			stripped := make(map[string]json.RawMessage)
263→			copyField(stripped, block, "type")
264→			copyField(stripped, block, "id")
265→			copyField(stripped, block, "name")
266→			copyField(stripped, block, "input")
267→			result = append(result, stripped)
268→			continue
269→		}
270→
271→		result = append(result, block)
272→	}
273→
274→	b, err := json.Marshal(result)
275→	if err != nil {
276→		return contentRaw
277→	}
278→	return b
279→}
