281→// minimizeToolUseResult keeps only fields needed for replaying tool calls
282→// (type, file metadata, error, answers). Output text and other verbose
283→// fields are dropped to reduce transcript size.
284→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
285→	var obj map[string]json.RawMessage
286→	if json.Unmarshal(raw, &obj) != nil {
287→		return raw
288→	}
289→
290→	return marshalOrdered(
291→		"type", obj["type"],
292→		"file", obj["file"],
293→		"error", obj["error"],
294→		"answers", obj["answers"],
295→	)
296→}
